//
//  FieldVisionApp.swift
//  FieldVision
//
//  Entry point. Info.plist keys (camera usage, background audio, portrait
//  only) are declared in project.yml and generated by XcodeGen.
//
//  Live mode needs a LiDAR device (iPhone 12 Pro or newer Pro / Pro Max,
//  iPad Pro 2020+). Everywhere else — including the Simulator — the app runs
//  the built-in demo scene through the exact same pipeline.
//

import SwiftUI

@main
struct FieldVisionApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
                // A bright screen in a pocket wastes battery, and many users
                // with low vision are light-sensitive.
                .preferredColorScheme(.dark)
        }
    }
}
